    Bug 1936369 - Attempt to fix browser_accountTelemetry.js by waiting for folder update after message additions. r=mkmelin

    The effect can be observed in the following try run:

    Run: https://treeherder.mozilla.org/jobs?repo=try-comm-central&selectedTaskRun=SklycsxnQw6U-5aHMieXMw.0&revision=1b41427bf21bc71b9c2ed8b332c3dcd5d1d07a89
    Log: https://treeherder.mozilla.org/logviewer?job_id=496478297&repo=try-comm-central&lineNumber=3668-3671
    Test: https://hg.mozilla.org/try-comm-central/rev/6e25e42823f2a227b09089d0217529e5bc645af2#l3.90

    Instead of fixing just this test, I think we can update the
    actual function used by multiple tests to add messages.

    Differential Revision: https://phabricator.services.mozilla.com/D239512

diff --git a/mailnews/test/resources/MessageInjection.sys.mjs b/mailnews/test/resources/MessageInjection.sys.mjs
index 8befa0dd18c..4cc21e586b4 100644
--- a/mailnews/test/resources/MessageInjection.sys.mjs
+++ b/mailnews/test/resources/MessageInjection.sys.mjs
@@ -697,6 +697,15 @@ export class MessageInjection {
       for (const folder of msgFolders) {
         folder.callFilterPlugins(null);
       }
+
+      if (doNotForceUpdate) {
+        return;
+      }
+      for (const folder of msgFolders) {
+        await new Promise(resolve => {
+          mailTestUtils.updateFolderAndNotify(folder, resolve);
+        });
+      }
     } else if (this._mis.injectionConfig.mode == "imap") {
       iterFolders = this._looperator(msgFolders);
       // we need to call updateFolder on all the folders, not just the first
